import React from 'react';
import * as CustomCode from '../CustomCode';

const isNotificationsPermissionGranted = async Variables => {
  console.log(`testPermissions: ${Variables.testPermissions}`);
  if (Variables.testPermissions) return false;

  const isDevice =
    CustomCode.Device.isDevice && CustomCode.Platform.OS !== 'web';

  if (isDevice && Variables.enableNotifications) {
    const settings = await CustomCode.ExpoNotifications.getPermissionsAsync();
    console.log(
      `Notif Permissions status: ${settings?.status}, ios: ${settings?.ios}`
    );

    return (
      settings?.granted ||
      settings?.ios?.status ===
        CustomCode.ExpoNotifications.IosAuthorizationStatus.AUTHORIZED
    );
  } else return true;
};

export default isNotificationsPermissionGranted;
