import React from 'react';
import * as CustomCode from '../CustomCode';
import * as DcSSApi from '../apis/DcSSApi.js';
import * as GlobalVariables from '../config/GlobalVariableContext';
import Images from '../config/Images';
import getNotificationToken from '../global-functions/getNotificationToken';
import isNotificationsPermissionGranted from '../global-functions/isNotificationsPermissionGranted';
import * as Utils from '../utils';
import Breakpoints from '../utils/Breakpoints';
import * as StyleSheet from '../utils/StyleSheet';
import useWindowDimensions from '../utils/useWindowDimensions';
import { Button, ScreenContainer, Touchable, withTheme } from '@draftbit/ui';
import { useIsFocused } from '@react-navigation/native';
import { Image, Text, View } from 'react-native';

const PermisoDeNotificacionesScreen = props => {
  const { theme, navigation } = props;
  const dimensions = useWindowDimensions();
  const Constants = GlobalVariables.useValues();
  const Variables = Constants;
  const askPermission = async () => {
    if (CustomCode.Platform.OS === 'web') return true;

    const { status, ios } =
      await CustomCode.ExpoNotifications.requestPermissionsAsync({
        ios: {
          allowAlert: true,
          allowBadge: true,
          allowSound: true,
          allowAnnouncements: true,
        },
      });

    console.log(`status: ${status}, ios: ${ios}`);

    if (CustomCode.Platform.OS === 'ios')
      return (
        ios.status ==
        CustomCode?.ExpoNotifications?.IosAuthorizationStatus?.AUTHORIZED
      );
    else return status === 'granted';
  };

  const showVars = () => {
    // console.log(`expo manifest.id: ${CustomCode.ExpoConstants}`);
    // console.log(`ExpoConstants: ${JSON.stringify(CustomCode.ExpoConstants)}`);
    // console.log(`expo manifest.id: ${JSON.stringify(CustomCode.ExpoConstants.manifest)}`);
    // console.log(`expo currentFullName: ${CustomCode.ExpoConstants.ExpoClientConfig.currentFullName}`);
  };
  const dcSSEmployeeTokenPATCH = DcSSApi.useEmployeeTokenPATCH();
  const isFocused = useIsFocused();
  React.useEffect(() => {
    const handler = async () => {
      try {
        if (!isFocused) {
          return;
        }
        showVars();
        const hasNotificationsPermission =
          await isNotificationsPermissionGranted(Variables);
        if (!hasNotificationsPermission) {
          return;
        }
        navigation.navigate('Permissions', { screen: 'PermisoDeCamaraScreen' });
      } catch (err) {
        console.error(err);
      }
    };
    handler();
  }, [isFocused]);

  return (
    <ScreenContainer
      scrollable={false}
      hasSafeArea={true}
      style={StyleSheet.applyWidth(
        {
          backgroundColor: theme.colors.background,
          justifyContent: 'space-between',
        },
        dimensions.width
      )}
    >
      <Utils.CustomCodeErrorBoundary>
        <CustomCode.DigicardScreenHeader {...props} left={{}} />
      </Utils.CustomCodeErrorBoundary>
      <View
        style={StyleSheet.applyWidth(
          {
            alignContent: 'center',
            alignItems: 'center',
            alignSelf: 'center',
            justifyContent: 'center',
          },
          dimensions.width
        )}
      >
        <Image
          resizeMode={'contain'}
          source={Images.PermissionsNotification}
          style={StyleSheet.applyWidth(
            { height: 150, marginBottom: 16, overflow: 'hidden', width: 150 },
            dimensions.width
          )}
        />
        <Text
          accessible={true}
          ellipsizeMode={'tail'}
          style={StyleSheet.applyWidth(
            {
              alignSelf: 'center',
              color: theme.colors.strong,
              fontFamily: 'System',
              fontSize: 28,
              fontWeight: '700',
            },
            dimensions.width
          )}
          textBreakStrategy={'highQuality'}
        >
          {'Permitir Notificaciones'}
        </Text>

        <Text
          accessible={true}
          ellipsizeMode={'tail'}
          style={StyleSheet.applyWidth(
            {
              alignSelf: 'center',
              color: theme.colors.strong,
              fontSize: 16,
              lineHeight: 28,
              marginLeft: '5%',
              marginRight: '5%',
              marginTop: '5%',
              textAlign: 'center',
            },
            dimensions.width
          )}
          textBreakStrategy={'highQuality'}
        >
          {
            'Digicard Self Service requiere que permita las notificaciones a fin de informarlo de novedades importantes acerca de su actividad con la aplicación (solicitudes y sus respuestas, mensajes de RRHH, etc)\n'
          }
        </Text>
      </View>

      <View
        style={StyleSheet.applyWidth(
          {
            alignContent: 'center',
            alignItems: 'center',
            justifyContent: 'flex-end',
            marginBottom: '10%',
            marginLeft: '6%',
            marginRight: '6%',
          },
          dimensions.width
        )}
      >
        <Touchable
          onPress={() => {
            try {
              navigation.navigate('Permissions', {
                screen: 'PermisoDeCamaraScreen',
              });
            } catch (err) {
              console.error(err);
            }
          }}
          style={StyleSheet.applyWidth(
            { marginBottom: '8%' },
            dimensions.width
          )}
        >
          <>
            {!false ? null : (
              <Text
                accessible={true}
                ellipsizeMode={'tail'}
                style={StyleSheet.applyWidth(
                  {
                    color: theme.colors['Strong'],
                    textAlign: 'center',
                    textTransform: 'uppercase',
                  },
                  dimensions.width
                )}
                textBreakStrategy={'highQuality'}
              >
                {'Saltar'}
              </Text>
            )}
          </>
        </Touchable>
        {/* Button Solid */}
        <Button
          iconPosition={'left'}
          onPress={() => {
            const handler = async () => {
              try {
                const granted = await askPermission();
                if (!granted) {
                  return;
                }
                const notificationTokenG = await getNotificationToken(
                  Variables
                );
                /* hidden 'API Request' action */
                navigation.navigate('Permissions', {
                  screen: 'PermisoDeCamaraScreen',
                });
              } catch (err) {
                console.error(err);
              }
            };
            handler();
          }}
          style={StyleSheet.applyWidth(
            {
              backgroundColor: theme.colors.primary,
              borderRadius: 10,
              color: theme.colors.background,
              fontFamily: 'System',
              fontWeight: '700',
              marginLeft: '6%',
              marginRight: '6%',
              minHeight: 48,
              textAlign: 'center',
              width: '100%',
            },
            dimensions.width
          )}
          title={'Permitir Notificaciones'}
        />
      </View>
    </ScreenContainer>
  );
};

export default withTheme(PermisoDeNotificacionesScreen);
